package ama.storage;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.nio.file.*;import java.io.IOException;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.dao.DataAccessResourceFailureException;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
/** Actual fixture methods plus full-column PUBLIC evidence shapes. No SQL/network/private reads. */
class Task11B3LifecycleReviewRegressionTest {
 final List<Path> temporary=new ArrayList<>();
 Path root(){return Path.of(System.getenv("AMA_TASK11_REPOSITORY_ROOT"));}
 Path work(){return root().resolve(".superpowers/sdd/2026-10-23-ama-phase-b-remaining");}
 Path directory()throws Exception {Path p=Files.createTempDirectory(root().resolve(".superpowers"),"b3-lifecycle-review-test-");temporary.add(p);return p;}
 Task11B3LifecycleFixture fixture(Path evidence)throws Exception {var f=new Task11B3LifecycleFixture();var cfg=Task11B2RuntimeFixture.JSON.readTree(Files.readAllBytes(work().resolve(Task11B3LifecycleInputs.ACK)));var empty=Task11B2RuntimeFixture.JSON.createObjectNode();f.inputs=new Task11B3LifecycleInputs.Inputs(root(),work(),root().resolve(".tools").resolve(Task11B3LifecycleInputs.OWNER),evidence,cfg,empty,empty,empty);return f;}
 @AfterEach void cleanup()throws Exception {for(Path p:temporary){assertTrue(p.toRealPath().startsWith(root().resolve(".superpowers").toRealPath())&&p.getFileName().toString().startsWith("b3-lifecycle-review-test-"));try(var stream=Files.walk(p)){for(Path file:stream.sorted(Comparator.reverseOrder()).toList())Files.delete(file);}}}
 JsonNode adoptedRelay(Task11B3LifecycleFixture f)throws Exception {return Task11B3LifecycleInputs.pin(work(),f.inputs.configuration(),"preparedFacts").path("relayBeforeAfter").deepCopy();}
 @Test void actualFixtureAcceptsFullAdoptedRelayAndExactFutureCounterIncrements()throws Exception {var f=fixture(directory());var relay=adoptedRelay(f);assertEquals(12,relay.size());assertDoesNotThrow(()->f.validateRelay(relay,0,0));((ObjectNode)relay).put("get",46).put("postAuthorization",25);assertDoesNotThrow(()->f.validateRelay(relay,7,8));}
 @Test void actualFixtureRejectsChangedCountersIdentitiesReceiptDigestAndExtraFields()throws Exception {var f=fixture(directory());for(String field:List.of("get","pid","pgid","port","upstream","receipt","responseSha256","unexpected")){ObjectNode relay=(ObjectNode)adoptedRelay(f);if(field.equals("receipt"))((ObjectNode)relay.path("receipt")).put("executionId","changed");else if(field.equals("responseSha256")||field.equals("unexpected"))relay.put(field,"changed");else relay.put(field,0);assertThrows(AssertionError.class,()->f.validateRelay(relay,0,0),field);}}
 @Test void completeOracleAcceptsFullNineteenTableShapeAndRejectsReceiptOrAssociationTamper()throws Exception {var s=new Task11B3LifecycleOracleShapes();assertDoesNotThrow(s::complete);var receipt=Task11B3LifecycleOracle.added(s.before,s.after,s.keys,"idempotency_record").getFirst();receipt.put("actor_id","foreign");assertThrows(AssertionError.class,s::complete);s=new Task11B3LifecycleOracleShapes();Task11B3LocalOracle.row(s.after,"publication_submission","task_id",s.tasks.getFirst()).put("local_execution_id",s.executions.getLast());assertThrows(AssertionError.class,s::complete);}
 @Test void queryOnlyOracleAcceptsExactFullShapeAndRejectsOtherWritesAndWrongOutboxTask()throws Exception {var s=new Task11B3LifecycleOracleShapes();var marked=Task11B3LifecycleOracleShapes.copy(s.after);var op=Task11B3LifecycleOracleShapes.row(marked,"external_operation",s.operation);op.put("state","MARKED");op.put("reconcile_epoch",((Number)op.get("reconcile_epoch")).longValue()-1);op.put("reconcile_owner","b3-lifecycle-marker-wins");Task11B3LifecycleOracleShapes.row(marked,"external_execution",s.executions.getLast()).put("state","MARKED");marked.get("task_outbox").removeIf(row->"EXTERNAL_UNKNOWN".equals(row.get("event_type"))&&s.tasks.getLast().equals(row.get("task_id")));var seq=marked.get("task_outbox_sequence").getFirst();seq.put("next_id",((Number)seq.get("next_id")).longValue()-1);
  assertDoesNotThrow(()->Task11B3LifecycleOracle.queryOnlyUnknown(marked,s.after,s.keys,s.operation,s.executions.getLast(),s.tasks.getLast()));var outbox=s.after.get("task_outbox").stream().filter(row->"EXTERNAL_UNKNOWN".equals(row.get("event_type"))&&s.tasks.getLast().equals(row.get("task_id"))).findFirst().orElseThrow();outbox.put("task_id",s.tasks.getFirst());assertThrows(AssertionError.class,()->Task11B3LifecycleOracle.queryOnlyUnknown(marked,s.after,s.keys,s.operation,s.executions.getLast(),s.tasks.getLast()));outbox.put("task_id",s.tasks.getLast());Task11B3LifecycleOracleShapes.row(s.after,"publication",s.publication).put("state","FAILED");assertThrows(AssertionError.class,()->Task11B3LifecycleOracle.queryOnlyUnknown(marked,s.after,s.keys,s.operation,s.executions.getLast(),s.tasks.getLast()));
 }
 Task11B3LifecycleFixture historyFixture(Task11B3LifecycleOracleShapes s)throws Exception {var f=fixture(directory());f.initial=s.before;f.keys.putAll(s.keys);f.tasks.addAll(s.tasks);f.executions.addAll(s.executions);f.meeting=s.meeting;f.publication=s.publication;f.operation=s.operation;f.sealed.add(Task11B3LifecycleOracle.seal(s.after,s.keys,s.tasks.getFirst(),s.executions.getFirst()));f.j=mock(JdbcTemplate.class);when(f.j.queryForList(startsWith("SELECT * FROM "))).thenAnswer(call->{String sql=call.getArgument(0);return s.after.get(sql.split(" ")[3]);});return f;}
 @Test void realSnapshotKeepsClosedSuccessorEntireRowsAcrossLaterPhases()throws Exception {var s=new Task11B3LifecycleOracleShapes();var f=historyFixture(s);assertDoesNotThrow(()->f.snapshot("positive"));for(String field:List.of("outcome","ended_at","owner","error_code")){var row=s.after.get("task_attempt").stream().filter(r->s.tasks.getFirst().equals(r.get("task_id"))).findFirst().orElseThrow();Object old=row.put(field,"tampered");assertThrows(AssertionError.class,()->f.snapshot("tampered-attempt-"+field),field);row.put(field,old);}for(String field:List.of("lease_owner","expires_at","producer_key","last_error","created_at")){var row=Task11B3LifecycleOracleShapes.row(s.after,"durable_task",s.tasks.getFirst());Object old=row.put(field,"tampered");assertThrows(AssertionError.class,()->f.snapshot("tampered-task-"+field),field);row.put(field,old);}}
 @Test void realSnapshotKeepsClosedManifestsReceiptsAndOutboxFieldsAndCounts()throws Exception {var s=new Task11B3LifecycleOracleShapes();var f=historyFixture(s);for(String table:List.of("external_execution","publication_submission","idempotency_record","audit_event","task_outbox")){var row=table.equals("external_execution")?Task11B3LifecycleOracleShapes.row(s.after,table,s.executions.getFirst()):table.equals("publication_submission")?Task11B3LocalOracle.row(s.after,table,"task_id",s.tasks.getFirst()):Task11B3LifecycleOracle.added(s.before,s.after,s.keys,table).getFirst();String field=table.equals("external_execution")||table.equals("publication_submission")?"request_manifest":table.equals("idempotency_record")?"request_hash":table.equals("audit_event")?"result":"reference_id";Object old=row.put(field,"tampered");assertThrows(AssertionError.class,()->f.snapshot("tampered-"+table),table);row.put(field,old);}var attempt=new HashMap<>(s.after.get("task_attempt").stream().filter(r->s.tasks.getFirst().equals(r.get("task_id"))).findFirst().orElseThrow());attempt.put("attempt",2);s.after.get("task_attempt").add(attempt);assertThrows(AssertionError.class,()->f.snapshot("extra-closed-attempt"));}
 Task11B3LifecycleFixture cleanupFixture()throws Exception {Path evidence=directory().resolve("evidence-is-a-file");Files.writeString(evidence,"owned failure boundary");var f=fixture(evidence);f.insertAttempted=true;f.inserted=true;f.hash="owned-session-hash";f.j=mock(JdbcTemplate.class);when(f.j.update(Task11B2ExactRetryReadbackIT.DELETE_SESSION,f.hash)).thenReturn(1);when(f.j.queryForObject("SELECT COUNT(*) FROM identity_session WHERE token_hash=?",Integer.class,f.hash)).thenReturn(0);return f;}
 @Test void actualDeleteSessionStillDeletesAndChecksAbsenceWhenIntentAndReturnedRecordsFail()throws Exception {var f=cleanupFixture();var error=assertThrows(IOException.class,f::deleteSession);verify(f.j,times(1)).update(Task11B2ExactRetryReadbackIT.DELETE_SESSION,f.hash);verify(f.j,times(1)).queryForObject("SELECT COUNT(*) FROM identity_session WHERE token_hash=?",Integer.class,f.hash);assertTrue(f.deleteAttempted&&f.sessionDeleted);assertTrue(error.getSuppressed().length>=1);assertDoesNotThrow(f::deleteSession);verifyNoMoreInteractions(f.j);}
 @Test void actualDeleteSessionAggregatesSqlFailureAndStillChecksAbsenceWithoutBlindRetry()throws Exception {var f=cleanupFixture();var sql=new DataAccessResourceFailureException("Owned exact delete failure");when(f.j.update(Task11B2ExactRetryReadbackIT.DELETE_SESSION,f.hash)).thenThrow(sql);var error=assertThrows(IOException.class,f::deleteSession);assertTrue(Arrays.asList(error.getSuppressed()).contains(sql));verify(f.j,times(1)).update(Task11B2ExactRetryReadbackIT.DELETE_SESSION,f.hash);verify(f.j,times(1)).queryForObject("SELECT COUNT(*) FROM identity_session WHERE token_hash=?",Integer.class,f.hash);assertTrue(f.deleteAttempted);assertFalse(f.sessionDeleted);assertDoesNotThrow(f::deleteSession);verifyNoMoreInteractions(f.j);}
 @Test void actualCloseRetainsInterruptionWhileRecordFailureCannotSkipSessionCleanup()throws Exception {var f=cleanupFixture();try{Thread.currentThread().interrupt();assertThrows(IOException.class,f::close);assertTrue(Thread.interrupted(),"Outer close preserves incoming interruption");assertTrue(f.sessionDeleted&&f.deleteCalled&&f.absenceChecked);verify(f.j,times(1)).update(Task11B2ExactRetryReadbackIT.DELETE_SESSION,f.hash);verify(f.j,times(1)).queryForObject("SELECT COUNT(*) FROM identity_session WHERE token_hash=?",Integer.class,f.hash);}finally{Thread.interrupted();}}
}